    // 1. Configuration Validation
    if (!isfinite(dt_config.filter_alpha) || dt_config.filter_alpha < 0.0 || dt_config.filter_alpha > 1.0 ||
        !isfinite(dt_config.coarse_gain_a_m2_s_t) || dt_config.coarse_gain_a_m2_s_t < 0.0 ||
        !isfinite(dt_config.fine_gain_a_m2_s_t) || dt_config.fine_gain_a_m2_s_t < 0.0 ||
        !isfinite(dt_config.max_dipole_a_m2) || dt_config.max_dipole_a_m2 < 0.0 ||
        !isfinite(dt_config.max_dipole_slew_a_m2_per_cycle) || dt_config.max_dipole_slew_a_m2_per_cycle < 0.0 ||
        !isfinite(dt_config.minimum_field_t) || dt_config.minimum_field_t < 0.0 ||
        !isfinite(dt_config.maximum_field_t) || dt_config.maximum_field_t < 0.0 ||
        !isfinite(dt_config.max_sample_gap_s) || dt_config.max_sample_gap_s < 0.0 ||
        !isfinite(dt_config.stop_rate_t_s) || dt_config.stop_rate_t_s < 0.0 ||
        !isfinite(dt_config.restart_rate_t_s) || dt_config.restart_rate_t_s < 0.0 ||
        !isfinite(dt_config.fine_enter_rate_t_s) || dt_config.fine_enter_rate_t_s < 0.0 ||
        !isfinite(dt_config.fine_exit_rate_t_s) || dt_config.fine_exit_rate_t_s < 0.0 ||
        dt_config.required_good < 1 || dt_config.required_good > 20 ||
        dt_config.max_bad < 1 || dt_config.max_bad > 20 ||
        dt_config.stop_rate_t_s >= dt_config.restart_rate_t_s ||
        dt_config.restart_rate_t_s >= dt_config.fine_enter_rate_t_s ||
        dt_config.fine_enter_rate_t_s >= dt_config.fine_exit_rate_t_s) {

        // Invalid config treated as rejected sample
        dt_state.bad++;
        dt_state.good = 0;
        dt_output.mode = dt_state.mode;
        dt_output.good = dt_state.good;
        dt_output.bad = dt_state.bad;
        dt_output.saturation_mask = 0U;
        dt_output.slew_mask = 0U;
        dt_output.filter_primed_this_cycle = 0;
        dt_output.field_magnitude_t = 0.0;
        dt_output.rate_norm_t_s = 0.0;
        dt_output.rate_t_s.x = 0.0;
        dt_output.rate_t_s.y = 0.0;
        dt_output.rate_t_s.z = 0.0;
        dt_output.dipole_a_m2.x = 0.0;
        dt_output.dipole_a_m2.y = 0.0;
        dt_output.dipole_a_m2.z = 0.0;
        return;
    }

    // 2. Enable Check
    if (!dt_input.valid) {
        dt_state.mode = DT_OFF;
        dt_state.good = 0;
        dt_state.bad = 0;
        dt_state.filter.initialized = 0;
        dt_state.filtered_rate_t_s.x = 0.0;
        dt_state.filtered_rate_t_s.y = 0.0;
        dt_state.filtered_rate_t_s.z = 0.0;
        dt_state.previous_dipole_a_m2.x = 0.0;
        dt_state.previous_dipole_a_m2.y = 0.0;
        dt_state.previous_dipole_a_m2.z = 0.0;

        dt_output.mode = DT_OFF;
        dt_output.good = 0;
        dt_output.bad = 0;
        dt_output.saturation_mask = 0U;
        dt_output.slew_mask = 0U;
        dt_output.filter_primed_this_cycle = 0;
        dt_output.field_magnitude_t = 0.0;
        dt_output.rate_norm_t_s = 0.0;
        dt_output.rate_t_s.x = 0.0;
        dt_output.rate_t_s.y = 0.0;
        dt_output.rate_t_s.z = 0.0;
        dt_output.dipole_a_m2.x = 0.0;
        dt_output.dipole_a_m2.y = 0.0;
        dt_output.dipole_a_m2.z = 0.0;
        return;
    }

    // 3. Input Validity
    if (dt_input.field_body_t == NULL || !adcs_is_finite_vec3(dt_input.field_body_t)) {
        goto rejected_sample;
    }

    // 4. Re-prime Logic
    int do_reprime = 0;
    if (!dt_state.filter.initialized) {
        do_reprime = 1;
    } else {
        double dt_time = dt_input.time_s - dt_state.filter.previous_time_s;
        if (isfinite(dt_time) && dt_time > dt_config.max_sample_gap_s) {
            do_reprime = 1;
        }
    }

    if (do_reprime) {
        dt_state.mode = DT_COARSE;
        dt_state.good = 0;
        dt_state.filter.previous_field_t = *dt_input.field_body_t;
        dt_state.filter.previous_time_s = dt_input.time_s;
        dt_state.filter.initialized = 1;
        dt_state.filtered_rate_t_s.x = 0.0;
        dt_state.filtered_rate_t_s.y = 0.0;
        dt_state.filtered_rate_t_s.z = 0.0;

        dt_output.mode = DT_COARSE;
        dt_output.good = 0;
        dt_output.bad = dt_state.bad;
        dt_output.filter_primed_this_cycle = 1;
        dt_output.field_magnitude_t = 0.0;
        dt_output.rate_norm_t_s = 0.0;
        dt_output.rate_t_s.x = 0.0;
        dt_output.rate_t_s.y = 0.0;
        dt_output.rate_t_s.z = 0.0;
        dt_output.dipole_a_m2.x = 0.0;
        dt_output.dipole_a_m2.y = 0.0;
        dt_output.dipole_a_m2.z = 0.0;
        dt_output.saturation_mask = 0U;
        dt_output.slew_mask = 0U;
        return;
    }

    // 5. Filter Update
    adcs_bdot_state_t filter_copy = dt_state.filter;
    adcs_vec3_t filtered_rate;
    adcs_status_t status = adcs_bdot_update(&filter_copy, dt_input.field_body_t, dt_input.time_s, 
                                            dt_config.filter_alpha, &filtered_rate);
    if (status != ADCS_OK) {
        goto rejected_sample;
    }
    dt_state.filter = filter_copy;
    dt_state.filtered_rate_t_s = filtered_rate;

    // 6. Field Magnitude Check
    double field_mag = adcs_vec3_norm(dt_input.field_body_t);
    dt_output.field_magnitude_t = field_mag;
    if (field_mag < dt_config.minimum_field_t || field_mag > dt_config.maximum_field_t) {
        goto rejected_sample;
    }

    // 7. Mode Transitions
    double rate_norm = adcs_vec3_norm(&filtered_rate);
    dt_output.rate_norm_t_s = rate_norm;
    dt_output.rate_t_s = filtered_rate;

    if (dt_state.mode == DT_COMPLETE) {
        if (rate_norm >= dt_config.fine_exit_rate_t_s) {
            dt_state.mode = DT_COARSE;
        } else if (rate_norm >= dt_config.restart_rate_t_s) {
            dt_state.mode = DT_FINE;
        } else {
            dt_state.mode = DT_COMPLETE;
        }
    } else {
        if (dt_state.mode == DT_COARSE) {
            if (rate_norm <= dt_config.fine_enter_rate_t_s) {
                dt_state.mode = DT_FINE;
            }
        } else if (dt_state.mode == DT_FINE) {
            if (rate_norm > dt_config.fine_exit_rate_t_s) {
                dt_state.mode = DT_COARSE;
            } else if (rate_norm <= dt_config.stop_rate_t_s) {
                dt_state.good++;
                if (dt_state.good >= dt_config.required_good) {
                    dt_state.mode = DT_COMPLETE;
                    dt_state.good = 0;
                }
            } else {
                dt_state.good = 0;
            }
        }
    }

    // 8. Dipole Generation
    if (dt_state.mode == DT_COMPLETE) {
        dt_output.dipole_a_m2.x = 0.0;
        dt_output.dipole_a_m2.y = 0.0;
        dt_output.dipole_a_m2.z = 0.0;
        dt_output.saturation_mask = 0U;
        dt_output.slew_mask = 0U;
        dt_state.previous_dipole_a_m2.x = 0.0;
        dt_state.previous_dipole_a_m2.y = 0.0;
        dt_state.previous_dipole_a_m2.z = 0.0;
    } else {
        double gain = (dt_state.mode == DT_FINE) ? dt_config.fine_gain_a_m2_s_t : dt_config.coarse_gain_a_m2_s_t;
        adcs_actuator_command_t cmd;
        status = adcs_bdot_dipole(dt_input.field_body_t, &filtered_rate, gain, 
                                  dt_config.max_dipole_a_m2, &cmd);
        if (status != ADCS_OK) {
            cmd.command.x = 0.0; cmd.command.y = 0.0; cmd.command.z = 0.0;
            cmd.saturated_axes = 0U;
        }

        adcs_vec3_t new_dipole = cmd.command;
        unint32 slew_mask = 0U;
        double max_slew = dt_config.max_dipole_slew_a_m2_per_cycle;

        double dx = new_dipole.x - dt_state.previous_dipole_a_m2.x;
        double dy = new_dipole.y - dt_state.previous_dipole_a_m2.y;
        double dz = new_dipole.z - dt_state.previous_dipole_a_m2.z;

        if (fabs(dx) > max_slew) {
            slew_mask |= 1U << 0;
            new_dipole.x = dt_state.previous_dipole_a_m2.x + copysign(max_slew, dx);
        }
        if (fabs(dy) > max_slew) {
            slew_mask |= 1U << 1;
            new_dipole.y = dt_state.previous_dipole_a_m2.y + copysign(max_slew, dy);
        }
        if (fabs(dz) > max_slew) {
            slew_mask |= 1U << 2;
            new_dipole.z = dt_state.previous_dipole_a_m2.z + copysign(max_slew, dz);
        }

        dt_output.dipole_a_m2 = new_dipole;
        dt_output.saturation_mask = cmd.saturated_axes;
        dt_output.slew_mask = slew_mask;
        dt_state.previous_dipole_a_m2 = new_dipole;
    }

    // 9. Final Output
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    dt_output.filter_primed_this_cycle = 0;

    return;

rejected_sample:
